package com.osrsbingo;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(BingoConfig.GROUP)
public interface BingoConfig extends Config
{
	String GROUP = "osrsbingo";

	@ConfigSection(
		name = "Connection",
		description = "Which bingo board to talk to",
		position = 0
	)
	String connectionSection = "connection";

	@ConfigSection(
		name = "What to report",
		description = "Which kinds of loot are sent to the board",
		position = 1
	)
	String reportingSection = "reporting";

	@ConfigSection(
		name = "Proof",
		description = "Screenshot capture",
		position = 2
	)
	String proofSection = "proof";

	@ConfigSection(
		name = "Display & feedback",
		description = "In-client display options",
		position = 3
	)
	String displaySection = "display";

	@ConfigItem(
		keyName = "boardCode",
		name = "Board code",
		description = "Your team's board code from the bingo site. Treat it like a password.",
		section = connectionSection,
		position = 0,
		secret = true
	)
	default String boardCode()
	{
		return "";
	}

	@ConfigItem(
		keyName = "reportNpcLoot",
		name = "Boss & monster kills",
		description = "Report loot from NPC kills",
		section = reportingSection,
		position = 0
	)
	default boolean reportNpcLoot()
	{
		return true;
	}

	@ConfigItem(
		keyName = "reportEventLoot",
		name = "Raid & chest rewards",
		description = "Report loot from CoX, ToB, ToA, Barrows and other reward chests",
		section = reportingSection,
		position = 1
	)
	default boolean reportEventLoot()
	{
		return true;
	}

	@ConfigItem(
		keyName = "reportPickpocket",
		name = "Pickpocketing",
		description = "Report loot from pickpocketing. Only useful if your bingo has thieving tiles.",
		section = reportingSection,
		position = 2
	)
	default boolean reportPickpocket()
	{
		return false;
	}

	@ConfigItem(
		keyName = "attachScreenshots",
		name = "Attach screenshots",
		description = "Capture a screenshot of each reported drop as proof for the reviewer. "
			+ "Screenshots are sent to your bingo backend and saved locally under "
			+ "screenshots/osrs-bingo.",
		section = proofSection,
		position = 0
	)
	default boolean attachScreenshots()
	{
		return true;
	}

	@ConfigItem(
		keyName = "notifyInChat",
		name = "Chat messages",
		description = "Post a chat line when a drop is logged, or when something goes wrong",
		section = displaySection,
		position = 1
	)
	default boolean notifyInChat()
	{
		return true;
	}
}

package com.osrsbingo.proof;

import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.Iterator;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import java.util.function.Consumer;
import javax.imageio.IIOImage;
import javax.imageio.ImageIO;
import javax.imageio.ImageWriteParam;
import javax.imageio.ImageWriter;
import javax.imageio.stream.FileImageOutputStream;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.util.ImageUtil;

/**
 * Captures a frame as proof, downscales it, writes a JPEG to disk, and hands
 * back the file.
 *
 * <p>JPEG rather than PNG or WebP: a game frame is photographic, so PNG runs
 * 1-2 MB where JPEG lands at ~200-300 KB, and Java 11's ImageIO has no WebP
 * writer (adding one needs a native library, which the Plugin Hub forbids).
 *
 * <p>Capture must never block a report: if no frame arrives within
 * {@link #CAPTURE_TIMEOUT_MS} the callback fires with null and the drop is
 * submitted without proof.
 */
@Slf4j
public class ScreenshotService
{
	private static final int MAX_WIDTH = 1280;
	private static final float JPEG_QUALITY = 0.85f;
	private static final long CAPTURE_TIMEOUT_MS = 2_000L;

	private static final DateTimeFormatter STAMP =
		DateTimeFormatter.ofPattern("yyyy-MM-dd_HH-mm-ss");

	private final DrawManager drawManager;
	private final ScheduledExecutorService executor;

	@Inject
	public ScreenshotService(DrawManager drawManager, ScheduledExecutorService executor)
	{
		this.drawManager = drawManager;
		this.executor = executor;
	}

	/**
	 * @param itemName used in the filename; must not be a board code
	 * @param callback invoked exactly once, with null when no proof is available
	 */
	public void capture(String itemName, Consumer<File> callback)
	{
		AtomicBoolean done = new AtomicBoolean();

		try
		{
			executor.schedule(() ->
			{
				if (done.compareAndSet(false, true))
				{
					log.debug("Bingo screenshot timed out; submitting without proof");
					callback.accept(null);
				}
			}, CAPTURE_TIMEOUT_MS, TimeUnit.MILLISECONDS);
		}
		catch (RuntimeException e)
		{
			// The timeout could not be armed (e.g. the executor is shutting
			// down during plugin teardown). Registering a frame listener now
			// would risk never firing the callback if no frame ever arrives,
			// so fail fast instead of leaving the drop stranded.
			if (done.compareAndSet(false, true))
			{
				log.debug("Bingo screenshot timeout could not be armed", e);
				callback.accept(null);
			}
			return;
		}

		try
		{
			drawManager.requestNextFrameListener(image ->
			{
				try
				{
					executor.submit(() ->
					{
						if (!done.compareAndSet(false, true))
						{
							return;
						}
						callback.accept(writeJpeg(image, itemName));
					});
				}
				catch (RuntimeException e)
				{
					if (done.compareAndSet(false, true))
					{
						log.debug("Bingo screenshot encoding could not be submitted", e);
						callback.accept(null);
					}
				}
			});
		}
		catch (RuntimeException e)
		{
			if (done.compareAndSet(false, true))
			{
				log.debug("Bingo screenshot request failed", e);
				callback.accept(null);
			}
		}
	}

	private File writeJpeg(Image image, String itemName)
	{
		try
		{
			BufferedImage source = ImageUtil.bufferedImageFromImage(image);
			BufferedImage scaled = downscale(source);
			File target = targetFile(itemName);
			writeJpeg(scaled, target);
			return target;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Failed to write bingo proof screenshot", e);
			return null;
		}
	}

	private static BufferedImage downscale(BufferedImage source)
	{
		if (source.getWidth() <= MAX_WIDTH)
		{
			return toRgb(source);
		}
		int width = MAX_WIDTH;
		int height = (int) Math.round(source.getHeight() * (MAX_WIDTH / (double) source.getWidth()));
		BufferedImage target = new BufferedImage(width, height, BufferedImage.TYPE_INT_RGB);
		Graphics2D g = target.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_INTERPOLATION,
			RenderingHints.VALUE_INTERPOLATION_BILINEAR);
		g.drawImage(source, 0, 0, width, height, null);
		g.dispose();
		return target;
	}

	/** JPEG has no alpha channel; an ARGB source must be flattened first. */
	private static BufferedImage toRgb(BufferedImage source)
	{
		if (source.getType() == BufferedImage.TYPE_INT_RGB)
		{
			return source;
		}
		BufferedImage target = new BufferedImage(source.getWidth(), source.getHeight(),
			BufferedImage.TYPE_INT_RGB);
		Graphics2D g = target.createGraphics();
		g.drawImage(source, 0, 0, null);
		g.dispose();
		return target;
	}

	private static void writeJpeg(BufferedImage image, File target) throws IOException
	{
		Iterator<ImageWriter> writers = ImageIO.getImageWritersByFormatName("jpg");
		if (!writers.hasNext())
		{
			throw new IOException("No JPEG writer available");
		}
		ImageWriter writer = writers.next();
		try (FileImageOutputStream out = new FileImageOutputStream(target))
		{
			writer.setOutput(out);
			ImageWriteParam params = writer.getDefaultWriteParam();
			if (params.canWriteCompressed())
			{
				params.setCompressionMode(ImageWriteParam.MODE_EXPLICIT);
				params.setCompressionQuality(JPEG_QUALITY);
			}
			writer.write(null, new IIOImage(image, null, null), params);
		}
		finally
		{
			writer.dispose();
		}
	}

	private static File targetFile(String itemName)
	{
		File dir = new File(RuneLite.RUNELITE_DIR, "screenshots" + File.separator + "osrs-bingo");
		if (!dir.exists() && !dir.mkdirs())
		{
			log.warn("Could not create bingo screenshot directory");
		}
		String safeName = itemName == null ? "drop" : itemName.replaceAll("[^A-Za-z0-9]+", "-");
		return new File(dir, LocalDateTime.now().format(STAMP) + "_" + safeName + ".jpg");
	}
}

package com.osrsbingo;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.osrsbingo.api.BingoApiClient;
import com.osrsbingo.api.DropResult;
import com.osrsbingo.board.BoardState;
import com.osrsbingo.chat.ChatNotifier;
import com.osrsbingo.drops.DropEvent;
import com.osrsbingo.drops.LootHandler;
import com.osrsbingo.drops.SubmissionQueue;
import com.osrsbingo.proof.ScreenshotService;
import com.osrsbingo.ui.BingoInfoOverlay;
import com.osrsbingo.ui.BingoOverlay;
import com.osrsbingo.ui.BingoPanel;
import com.osrsbingo.ui.OverlayVisibility;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Player;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.DrawManager;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import okhttp3.OkHttpClient;

@Slf4j
@PluginDescriptor(
	name = "OSRS Bingo",
	description = "Shows your clan bingo board in-game and auto-logs drops to it",
	tags = {"bingo", "clan", "drops", "loot", "board"}
)
public class BingoPlugin extends Plugin
{
	/** The bingo backend. Hardcoded — the site is private and not user-configurable. */
	private static final String BACKEND_URL = "https://bingo.osrs-clan-tools.com";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private BingoConfig config;

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private ItemManager itemManager;

	@Inject
	private DrawManager drawManager;

	@Inject
	private ChatNotifier chatNotifier;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	private BoardState boardState;
	private SubmissionQueue queue;
	private ScreenshotService screenshotService;
	private LootHandler lootHandler;
	private BingoPanel panel;
	private NavigationButton navButton;
	private BingoOverlay overlay;
	private BingoInfoOverlay infoOverlay;
	/**
	 * The exact {@link Runnable} instance registered with {@link
	 * BoardState#addListener}. A method reference like {@code panel::refresh}
	 * creates a NEW object each time it is written, so this must be captured
	 * once here to be removable later — passing a fresh {@code panel::refresh}
	 * to {@link BoardState#removeListener} would never match.
	 */
	private Runnable panelRefreshListener;

	@Override
	protected void startUp()
	{
		BingoApiClient api = new BingoApiClient(okHttpClient, gson, () -> BACKEND_URL);

		// Final locals, deliberately: shutDown() nulls the fields, and a drain
		// pass already in flight on the shared executor would otherwise NPE
		// reading them. The callbacks hold their own references instead.
		final BoardState state = new BoardState(api, executor, config,
			() -> client.getGameState() == GameState.LOGGED_IN);
		final ChatNotifier notifier = chatNotifier;
		boardState = state;

		queue = new SubmissionQueue(api, executor, System::currentTimeMillis,
			(result, itemName) -> onSubmissionSuccess(notifier, state, result, itemName),
			(drop, rejectedBoardCode, itemName, failure, proof) ->
			{
				// Spec §9: a rejection is board news, not just a chat line —
				// 404 kills the code, 409 means refetch status. It is news about
				// the board this drop was actually sent to, though: the queue
				// retries for up to an hour, so a 404 for a code the player has
				// since replaced must not kill the valid board now loaded.
				state.onSubmissionRejected(rejectedBoardCode, failure);
				// Every abandonment must reach the player — unlike failure(), this
				// is NOT debounced (see ChatNotifier#abandoned). Names the
				// screenshot so a lost drop can be submitted by hand. The filename
				// holds a timestamp and the item name, never the board code.
				notifier.abandoned(itemName, proof == null ? null : proof.getAbsolutePath());
			});

		screenshotService = new ScreenshotService(drawManager, executor);
		lootHandler = new LootHandler(boardState, config, this::localPlayerName, this::onDropsCaptured);

		boardState.start();
		queue.start();

		panel = new BingoPanel(boardState, itemManager, clientThread, configManager);
		panelRefreshListener = panel::refresh;
		boardState.addListener(panelRefreshListener);

		BufferedImage icon = ImageUtil.loadImageResource(BingoPlugin.class, "icon.png");
		navButton = NavigationButton.builder()
			.tooltip("OSRS Bingo")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		overlay = new BingoOverlay(boardState, () -> OverlayVisibility.isVisible(configManager));
		overlayManager.add(overlay);
		infoOverlay = new BingoInfoOverlay(boardState);
		overlayManager.add(infoOverlay);

		log.info("OSRS Bingo started");
	}

	@Override
	protected void shutDown()
	{
		if (boardState != null)
		{
			boardState.removeListener(panelRefreshListener);
			boardState.stop();
			boardState = null;
		}
		panelRefreshListener = null;
		if (queue != null)
		{
			// Cancel the drain loop BEFORE dropping the reference: the executor
			// is RuneLite's shared one, so an uncancelled task keeps POSTing
			// (and calling back) long after the plugin is gone.
			queue.stop();
			if (queue.size() > 0)
			{
				log.info("OSRS Bingo stopped with {} drop(s) still queued", queue.size());
			}
		}
		queue = null;
		lootHandler = null;
		screenshotService = null;
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;
		if (overlay != null)
		{
			overlayManager.remove(overlay);
			overlay = null;
		}
		if (infoOverlay != null)
		{
			overlayManager.remove(infoOverlay);
			infoOverlay = null;
		}
		log.info("OSRS Bingo stopped");
	}

	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (lootHandler != null)
		{
			lootHandler.onLootReceived(event);
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!BingoConfig.GROUP.equals(event.getGroup()) || boardState == null)
		{
			return;
		}
		if ("boardCode".equals(event.getKey()))
		{
			boardState.onBoardCodeChanged();
		}
	}

	private String localPlayerName()
	{
		Player local = client.getLocalPlayer();
		return local == null ? null : local.getName();
	}

	/**
	 * One capture per loot event, shared by every item in it — the file is
	 * written once and attached to each request.
	 *
	 * <p>Uses {@code invoke} rather than {@code invokeLater}: this is already on
	 * the client thread (called from the LootReceived subscriber), so the frame
	 * request goes out immediately instead of a tick later, while the reward
	 * interface is still on screen.
	 */
	private void onDropsCaptured(List<DropEvent> drops)
	{
		BoardState state = boardState;
		if (state == null)
		{
			return;
		}
		// NOT config.boardCode(): ConfigManager writes the new value before it
		// posts ConfigChanged, so a drop landing in that window would be
		// filtered by the old board's item set and reported to the new board —
		// a board that was never validated. Report only to the code the cached
		// board was actually fetched with, and not at all when there isn't one.
		String boardCode = state.getCachedBoardCode();
		if (boardCode == null || boardCode.isEmpty())
		{
			return;
		}

		// Captured, not read from the fields: the lambda below runs later and
		// shutDown() nulls them.
		final SubmissionQueue submissionQueue = queue;
		final ScreenshotService screenshots = screenshotService;
		if (submissionQueue == null || screenshots == null)
		{
			return;
		}

		int firstItemId = drops.get(0).getItemId();
		// Item names must be read on the client thread. Resolve every distinct
		// item in this loot event — one name per drop, so the chat line for a
		// delivered drop names that drop's item and not a neighbour's.
		clientThread.invoke(() ->
		{
			Map<Integer, String> itemNames = new HashMap<>();
			for (DropEvent drop : drops)
			{
				itemNames.computeIfAbsent(drop.getItemId(), this::resolveItemName);
			}
			String firstItemName = itemNames.get(firstItemId);

			if (!config.attachScreenshots())
			{
				submissionQueue.submit(drops, boardCode, null, itemNames);
				return;
			}
			screenshots.capture(firstItemName,
				(File image) -> submissionQueue.submit(drops, boardCode, image, itemNames));
		});
	}

	/** Client thread only. Never returns null — the name reaches a chat line. */
	private String resolveItemName(int itemId)
	{
		try
		{
			String name = itemManager.getItemComposition(itemId).getName();
			return name == null || name.isEmpty() ? "Drop" : name;
		}
		catch (RuntimeException e)
		{
			log.debug("Could not resolve name for item {}", itemId);
			return "Drop";
		}
	}

	/**
	 * Handles one delivered submission: always notify chat (it self-silences on
	 * a deduped drop), but only refetch the board when the backend actually
	 * created something. A deduped drop ({@code submissionCount == 0}) changed
	 * nothing server-side, so a refetch would be wasted.
	 */
	static void onSubmissionSuccess(ChatNotifier notifier, BoardState state, DropResult result, String itemName)
	{
		notifier.success(itemName, result.getSubmissionCount());
		if (result.getSubmissionCount() >= 1)
		{
			state.refreshSoon();
		}
	}

	@Provides
	BingoConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BingoConfig.class);
	}
}

package com.osrsbingo.chat;

import com.osrsbingo.BingoConfig;
import com.osrsbingo.api.ApiFailure;
import java.util.EnumMap;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;

/**
 * In-game feedback, debounced to one message per error class per five minutes
 * so a sustained outage cannot spam the chat box.
 */
public class ChatNotifier
{
	private static final long DEBOUNCE_MS = 300_000L;

	private final ChatMessageManager chatMessageManager;
	private final BingoConfig config;
	private final Map<ApiFailure.Kind, Long> lastSent = new EnumMap<>(ApiFailure.Kind.class);

	@Inject
	public ChatNotifier(ChatMessageManager chatMessageManager, BingoConfig config)
	{
		this.chatMessageManager = chatMessageManager;
		this.config = config;
	}

	public void success(String itemName, int submissionCount)
	{
		if (!config.notifyInChat() || submissionCount <= 0)
		{
			return;
		}
		send(itemName + " logged — " + submissionCount
			+ (submissionCount == 1 ? " tile." : " tiles."));
	}

	public void failure(ApiFailure.Kind kind, String detail)
	{
		if (!config.notifyInChat())
		{
			return;
		}
		long now = System.currentTimeMillis();
		Long previous = lastSent.get(kind);
		if (previous != null && now - previous < DEBOUNCE_MS)
		{
			return;
		}
		lastSent.put(kind, now);
		send(message(kind, detail));
	}

	/**
	 * Reports a drop that will never be delivered automatically — after up to an
	 * hour of retries, or a permanent (non-retryable) rejection. This is
	 * deliberately NOT subject to the per-{@link ApiFailure.Kind} five-minute
	 * debounce that {@link #failure(ApiFailure.Kind, String)} applies: these
	 * events are rare (one per genuinely lost drop), and unlike a transient
	 * connection blip, silently swallowing a second one within five minutes
	 * costs the player a rare drop they never learn they need to submit by
	 * hand. This is a deliberate, documented deviation from spec §8.4's
	 * blanket "one message per error class per five minutes" — losing an
	 * abandonment message silently is worse than the spam it would otherwise
	 * prevent.
	 *
	 * @param itemName the item that was dropped; never null in practice, but
	 *                 handled defensively
	 * @param screenshotPath absolute path to the saved proof screenshot so the
	 *                       player can submit by hand, or null when none was
	 *                       captured (screenshots disabled, or capture failed).
	 *                       Never the board code — a secret credential — which
	 *                       must never appear in this message.
	 */
	public void abandoned(String itemName, String screenshotPath)
	{
		if (!config.notifyInChat())
		{
			return;
		}
		String name = itemName == null || itemName.isEmpty() ? "A bingo drop" : itemName;
		String text = name + " couldn't be submitted automatically after repeated attempts."
			+ (screenshotPath == null
				? " No screenshot was saved — submit it by hand."
				: " Screenshot saved: " + screenshotPath + " — submit it by hand.");
		send(text);
	}

	private static String message(ApiFailure.Kind kind, String detail)
	{
		switch (kind)
		{
			case NOT_FOUND:
				return "Your bingo board code looks wrong or expired — check the plugin settings.";
			case UNAUTHORIZED:
				return "Your bingo board code was rejected — it may have been revoked."
					+ " Ask your event organiser for a new one.";
			case EVENT_NOT_ACTIVE:
				return "This bingo isn't active right now.";
			case AMBIGUOUS:
				// It may or may not have landed. Never resubmitted automatically —
				// a duplicate costs an admin a cleanup — so say so plainly.
				return "A bingo drop timed out and wasn't confirmed. It was NOT resubmitted,"
					+ " in case it already went through. Check the board, then submit by hand"
					+ (detail == null ? " if it's missing." : " if it's missing: " + detail);
			case NETWORK:
			case SERVER_ERROR:
			case RATE_LIMITED:
				return "Couldn't reach the bingo server. Saved a screenshot"
					+ (detail == null ? "." : ": " + detail);
			case PAYLOAD_TOO_LARGE:
			case VALIDATION:
			default:
				return "A bingo drop couldn't be submitted"
					+ (detail == null ? "." : ": " + detail);
		}
	}

	private void send(String text)
	{
		String message = new ChatMessageBuilder()
			.append(ChatColorType.HIGHLIGHT)
			.append("[Bingo] ")
			.append(ChatColorType.NORMAL)
			.append(text)
			.build();

		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(message)
			.build());
	}
}

package com.osrsbingo.drops;

import com.osrsbingo.api.ApiFailure;
import com.osrsbingo.api.ApiOutcome;
import com.osrsbingo.api.BingoApiClient;
import com.osrsbingo.api.DropResult;
import java.io.File;
import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.function.LongSupplier;
import lombok.extern.slf4j.Slf4j;

/**
 * Delivers drops with dedupe, request spacing, and patient retry.
 *
 * <p>Retries are deliberately long-lived: drops are rare and valuable, so a
 * router reboot must not cost a Twisted bow. Sends are spaced because the
 * backend's rate limit bucket is per board code and teammates share it.
 *
 * <p>The clock is injected so backoff and give-up are testable without waiting.
 */
@Slf4j
public class SubmissionQueue
{
	private static final long BASE_BACKOFF_MS = 2_000L;
	private static final long MAX_BACKOFF_MS = 300_000L;
	private static final long GIVE_UP_AFTER_MS = 3_600_000L;
	private static final long SEND_SPACING_MS = 400L;
	private static final long DRAIN_INTERVAL_MS = 1_000L;
	/**
	 * Cap on {@link #seen}. Comfortably more distinct drops than any real
	 * session produces, so eviction only ever removes keys far older than
	 * anything still in {@link #pending} — normal-scale dedupe is unaffected.
	 */
	private static final int SEEN_CAP = 10_000;

	/**
	 * Reports a delivered drop. Takes the item name that belongs to THAT drop —
	 * a shared "most recent name" field mis-names every chat line when two
	 * on-board drops are in flight at once.
	 */
	@FunctionalInterface
	public interface SuccessListener
	{
		void onSuccess(DropResult result, String itemName);
	}

	/**
	 * Reports a drop that will never be delivered. Receives the proof file so
	 * the give-up chat line can name it (spec §9): the automatic report is lost,
	 * but the screenshot on disk lets the player submit by hand.
	 *
	 * @param boardCode the code THIS drop was queued under, which after up to an
	 *                  hour of retries need not be the current one. Needed so a
	 *                  rejection is only ever applied to the board it came from.
	 *                  A credential: never log it, never put it in a message.
	 * @param itemName the item name carried on the drop's queue entry (resolved
	 *                 on the client thread at capture time), so the abandonment
	 *                 chat line names the right item even when several drops are
	 *                 in flight at once. Never a shared mutable "most recent
	 *                 name" field.
	 * @param proof the saved screenshot, or null when none was captured
	 */
	@FunctionalInterface
	public interface PermanentFailureListener
	{
		void onPermanentFailure(DropEvent drop, String boardCode, String itemName, ApiFailure failure, File proof);
	}

	private final BingoApiClient api;
	private final ScheduledExecutorService executor;
	private final LongSupplier clockMs;
	private final SuccessListener onSuccess;
	private final PermanentFailureListener onPermanentFailure;

	private final List<QueuedDrop> pending = new ArrayList<>();
	/**
	 * Every drop key ever submitted, so a re-enqueue of the same loot event is
	 * rejected. Bounded — drops are rare but the plugin's lifetime is not, so
	 * an unbounded set here would grow for as long as the client runs. Backed
	 * by a {@link LinkedHashMap} in insertion order, which evicts the OLDEST
	 * key once {@link #SEEN_CAP} is exceeded; only ever touched under this
	 * queue's monitor (see {@link #submit}), because {@code LinkedHashMap} is
	 * not thread-safe.
	 */
	private final Set<String> seen = Collections.newSetFromMap(new LinkedHashMap<String, Boolean>(16, 0.75f, false)
	{
		@Override
		protected boolean removeEldestEntry(Map.Entry<String, Boolean> eldest)
		{
			return size() > SEEN_CAP;
		}
	});

	/**
	 * Entries with a request outstanding. Identity-keyed (not equals/hashCode)
	 * because {@link QueuedDrop}'s Lombok-generated hashCode changes as its
	 * mutable fields (attempts, nextAttemptAt, dropImage) change, which would
	 * corrupt a regular HashSet while the entry sat in it.
	 */
	private final Set<QueuedDrop> inFlight = Collections.newSetFromMap(new IdentityHashMap<>());

	private long lastSendAt;

	/**
	 * Guards {@link #drainTask} against racing start()/stop() calls. Never held
	 * across a network call — start() and stop() only touch the future.
	 */
	private final Object lifecycleLock = new Object();
	private ScheduledFuture<?> drainTask;
	/**
	 * Set by {@link #stop()}. Checked by {@link #drainOnce()} as well as
	 * cancelling the future, because cancel(false) does not interrupt a pass
	 * that is already running and the executor is shared with the rest of
	 * RuneLite.
	 */
	private volatile boolean stopped;

	public SubmissionQueue(BingoApiClient api, ScheduledExecutorService executor, LongSupplier clockMs,
		SuccessListener onSuccess, PermanentFailureListener onPermanentFailure)
	{
		this.api = api;
		this.executor = executor;
		this.clockMs = clockMs;
		this.onSuccess = onSuccess;
		this.onPermanentFailure = onPermanentFailure;
	}

	public void start()
	{
		synchronized (lifecycleLock)
		{
			if (stopped || drainTask != null)
			{
				return;
			}
			drainTask = executor.scheduleWithFixedDelay(this::drainOnce, DRAIN_INTERVAL_MS,
				DRAIN_INTERVAL_MS, TimeUnit.MILLISECONDS);
		}
	}

	/**
	 * Cancels the drain loop and permanently stops draining. Idempotent and
	 * safe to call without a preceding {@link #start()}.
	 *
	 * <p>Must be called from the plugin's shutDown(): the executor is
	 * RuneLite's shared single-threaded one, so an uncancelled
	 * scheduleWithFixedDelay task outlives the plugin entirely — still POSTing
	 * drops, still writing chat lines, and still calling back into objects the
	 * plugin has already torn down. Toggling the plugin would leave one such
	 * loop per toggle.
	 */
	public void stop()
	{
		synchronized (lifecycleLock)
		{
			stopped = true;
			if (drainTask != null)
			{
				drainTask.cancel(false);
				drainTask = null;
			}
		}
	}

	/**
	 * Enqueues every item from one loot event. All items share the image file —
	 * one capture per loot event, not per item.
	 *
	 * @param itemNames item id to display name, resolved on the client thread by
	 *                  the caller. Each drop keeps its own name so the chat line
	 *                  for a delivered drop names the right item.
	 */
	public synchronized void submit(List<DropEvent> drops, String boardCode, File image,
		Map<Integer, String> itemNames)
	{
		long now = clockMs.getAsLong();
		for (DropEvent drop : drops)
		{
			String itemName = itemNames == null ? null : itemNames.get(drop.getItemId());
			QueuedDrop queued = new QueuedDrop(drop, boardCode,
				itemName == null || itemName.isEmpty() ? "Drop" : itemName, image, now);
			if (!seen.add(queued.key()))
			{
				log.debug("Skipping duplicate bingo drop for item {}", drop.getItemId());
				continue;
			}
			pending.add(queued);
		}
	}

	public synchronized int size()
	{
		return pending.size();
	}

	/**
	 * Attempts at most one send. Package-visible rather than private so tests
	 * can step the queue deterministically instead of sleeping.
	 *
	 * <p>Deliberately NOT {@code synchronized} as a whole: {@link
	 * BingoApiClient#submitDrop} is a blocking HTTP round-trip, and {@link
	 * #submit} — called from the RuneLite client thread once loot events are
	 * wired up — shares this object's monitor. Holding the lock across the
	 * network call would freeze the client for the duration of the request.
	 * Instead the entry to send (if any) is selected and snapshotted under the
	 * lock in {@link #select()}, the network call happens with no lock held,
	 * and the outcome is re-applied under the lock in {@link #applyOutcome}.
	 * The selected entry is marked in-flight for the duration so a concurrent
	 * {@code drainOnce()} cannot pick — and send — it a second time.
	 *
	 * <p>Never throws: this is invoked by {@code
	 * ScheduledExecutorService#scheduleWithFixedDelay}, which silently
	 * cancels all future runs if the task throws once. An unchecked
	 * exception from {@link BingoApiClient#submitDrop} is therefore caught
	 * and treated as a transient (network-like) failure — the entry is kept
	 * and backed off exactly as a {@code NETWORK} failure would be, never
	 * dropped and never left stuck in-flight — rather than a bug in the HTTP
	 * layer costing a player a rare drop or silently halting the whole
	 * queue.
	 */
	void drainOnce()
	{
		if (stopped)
		{
			return;
		}
		try
		{
			drainOnceUnsafe();
		}
		catch (RuntimeException e)
		{
			log.warn("Unexpected error while draining the bingo submission queue", e);
		}
	}

	private void drainOnceUnsafe()
	{
		Selection selection = select();
		if (selection == null)
		{
			return;
		}

		try
		{
			// Give-ups reach BoardState/Swing via onPermanentFailure; invoke outside the lock.
			for (QueuedDrop givenUp : selection.givenUp)
			{
				// getImage(), not effectiveImage(): a 413 retry stops SENDING the
				// file but it is still on disk, and naming it is the whole point.
				onPermanentFailure.onPermanentFailure(givenUp.getDrop(), givenUp.getBoardCode(),
					givenUp.getItemName(), ApiFailure.network(), givenUp.getImage());
			}

			if (selection.entry == null)
			{
				return;
			}

			ApiOutcome<DropResult> outcome;
			try
			{
				outcome = api.submitDrop(selection.boardCode, selection.drop, selection.image);
			}
			catch (RuntimeException e)
			{
				// Never log the board code (a secret credential) or the exception's
				// message/stack trace, which may embed the request URL. Log only the
				// exception type and the item id, and treat the failure as transient.
				log.warn("submitDrop threw {} for item {}; treating as a transient failure",
					e.getClass().getSimpleName(), selection.drop.getItemId());
				applyOutcome(selection.entry, selection.now, ApiOutcome.failed(ApiFailure.network()));
				return;
			}

			Result result = applyOutcome(selection.entry, selection.now, outcome);
			if (result.success != null)
			{
				onSuccess.onSuccess(result.success, result.itemName);
			}
			else if (result.permanentFailureDrop != null)
			{
				onPermanentFailure.onPermanentFailure(result.permanentFailureDrop,
					result.boardCode, result.itemName, result.permanentFailure, result.proof);
			}
		}
		finally
		{
			// Structural guarantee, not a targeted catch: whatever happens above
			// (including a throwing onPermanentFailure callback for a give-up
			// entry collected in the same select() call as selection.entry), the
			// selected entry must never be left permanently marked in-flight — or
			// select() would skip it forever while it stays in pending,
			// stranding the drop. applyOutcome() already clears it on every path
			// it reaches; this is a harmless no-op (Set#remove of an absent
			// element) when that already happened, and the only thing that
			// clears it when a path above throws before reaching applyOutcome().
			if (selection.entry != null)
			{
				clearInFlight(selection.entry);
			}
		}
	}

	private synchronized void clearInFlight(QueuedDrop queued)
	{
		inFlight.remove(queued);
	}

	/**
	 * Under the lock: applies the send-spacing gate, gives up on stale entries,
	 * and picks at most one due, not-already-in-flight entry to send. Marks
	 * that entry in-flight and snapshots everything the network call needs so
	 * the caller can send with no lock held.
	 */
	private synchronized Selection select()
	{
		long now = clockMs.getAsLong();
		List<QueuedDrop> givenUp = new ArrayList<>();
		QueuedDrop toSend = null;

		if (!pending.isEmpty() && now - lastSendAt >= SEND_SPACING_MS)
		{
			Iterator<QueuedDrop> iterator = pending.iterator();
			while (iterator.hasNext())
			{
				QueuedDrop queued = iterator.next();
				if (inFlight.contains(queued))
				{
					// Already being sent by a concurrent drainOnce(); never pick it again.
					continue;
				}
				if (now - queued.getFirstAttemptAt() > GIVE_UP_AFTER_MS)
				{
					iterator.remove();
					givenUp.add(queued);
					continue;
				}
				if (now < queued.getNextAttemptAt())
				{
					continue;
				}

				lastSendAt = now;
				queued.setAttempts(queued.getAttempts() + 1);
				inFlight.add(queued);
				toSend = queued;
				break;
			}
		}

		if (givenUp.isEmpty() && toSend == null)
		{
			return null;
		}

		if (toSend == null)
		{
			return new Selection(givenUp, null, now, null, null, null);
		}
		return new Selection(givenUp, toSend, now, toSend.getBoardCode(), toSend.getDrop(),
			toSend.effectiveImage());
	}

	/**
	 * Under the lock: applies the outcome of a completed send — remove on
	 * success or permanent failure, or update {@code dropImage} /
	 * {@code nextAttemptAt} for a retry — and clears the in-flight marker.
	 */
	private synchronized Result applyOutcome(QueuedDrop queued, long now, ApiOutcome<DropResult> outcome)
	{
		inFlight.remove(queued);

		if (outcome.isOk())
		{
			pending.removeIf(candidate -> candidate == queued);
			return Result.success(outcome.getValue(), queued.getItemName());
		}

		ApiFailure failure = outcome.getFailure();
		if (failure == null)
		{
			pending.removeIf(candidate -> candidate == queued);
			return Result.none();
		}
		if (failure.getKind() == ApiFailure.Kind.PAYLOAD_TOO_LARGE && !queued.isDropImage())
		{
			// Retry once without the proof image rather than losing the drop.
			queued.setDropImage(true);
			queued.setNextAttemptAt(now + BASE_BACKOFF_MS);
			return Result.none();
		}
		if (!failure.isTransient())
		{
			pending.removeIf(candidate -> candidate == queued);
			return Result.permanentFailure(queued.getDrop(), queued.getBoardCode(), queued.getItemName(),
				failure, queued.getImage());
		}

		queued.setNextAttemptAt(now + retryDelayMs(queued, failure));
		return Result.none();
	}

	private long retryDelayMs(QueuedDrop queued, ApiFailure failure)
	{
		if (failure.getRetryAfterSeconds() > 0L)
		{
			return failure.getRetryAfterSeconds() * 1_000L;
		}
		int exponent = Math.max(0, Math.min(queued.getAttempts() - 1, 16));
		long delay = BASE_BACKOFF_MS << exponent;
		if (delay <= 0L || delay > MAX_BACKOFF_MS)
		{
			delay = MAX_BACKOFF_MS;
		}
		// +/-20% jitter so a shared rate-limit bucket is not hammered in lockstep.
		double jitter = 0.8 + (Math.random() * 0.4);
		return (long) (delay * jitter);
	}

	/** Snapshot of what {@link #drainOnce()} should do outside the lock. */
	private static final class Selection
	{
		final List<QueuedDrop> givenUp;
		final QueuedDrop entry;
		final long now;
		final String boardCode;
		final DropEvent drop;
		final File image;

		Selection(List<QueuedDrop> givenUp, QueuedDrop entry, long now, String boardCode, DropEvent drop,
			File image)
		{
			this.givenUp = givenUp;
			this.entry = entry;
			this.now = now;
			this.boardCode = boardCode;
			this.drop = drop;
			this.image = image;
		}
	}

	/** Outcome of {@link #applyOutcome} for {@link #drainOnce()} to report outside the lock. */
	private static final class Result
	{
		final DropResult success;
		/** Name of the item this particular result belongs to. */
		final String itemName;
		final DropEvent permanentFailureDrop;
		/** The code the failed drop was queued under — see PermanentFailureListener. */
		final String boardCode;
		final ApiFailure permanentFailure;
		final File proof;

		private Result(DropResult success, String itemName, DropEvent permanentFailureDrop,
			String boardCode, ApiFailure permanentFailure, File proof)
		{
			this.success = success;
			this.itemName = itemName;
			this.permanentFailureDrop = permanentFailureDrop;
			this.boardCode = boardCode;
			this.permanentFailure = permanentFailure;
			this.proof = proof;
		}

		static Result success(DropResult value, String itemName)
		{
			return new Result(value, itemName, null, null, null, null);
		}

		static Result permanentFailure(DropEvent drop, String boardCode, String itemName,
			ApiFailure failure, File proof)
		{
			return new Result(null, itemName, drop, boardCode, failure, proof);
		}

		static Result none()
		{
			return new Result(null, null, null, null, null, null);
		}
	}
}

package com.osrsbingo.drops;

import com.osrsbingo.BingoConfig;
import com.osrsbingo.board.BoardState;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.Consumer;
import java.util.function.Supplier;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.loottracker.LootReceived;
import net.runelite.http.api.loottracker.LootRecordType;

/**
 * Filters RuneLite loot events down to drops that belong on the team's board.
 *
 * <p>Runs on the client thread: it reads immutable values into {@link DropEvent}
 * and hands them to a sink. No network, no disk, no blocking.
 *
 * <p>{@link LootRecordType#PLAYER} is never reported. Unlike NPC and EVENT loot,
 * a player kill can be staged between two cooperating accounts carrying any
 * item, so including it would undermine the plugin's anti-spoof guarantee.
 */
public class LootHandler
{
	private final BoardState boardState;
	private final BingoConfig config;
	private final Supplier<String> rsnSupplier;
	private final Consumer<List<DropEvent>> sink;
	private final AtomicLong sequence = new AtomicLong();

	public LootHandler(BoardState boardState, BingoConfig config, Supplier<String> rsnSupplier,
		Consumer<List<DropEvent>> sink)
	{
		this.boardState = boardState;
		this.config = config;
		this.rsnSupplier = rsnSupplier;
		this.sink = sink;
	}

	public void onLootReceived(LootReceived event)
	{
		if (!boardState.canReport() || !isEnabled(event.getType()))
		{
			return;
		}
		String rsn = rsnSupplier.get();
		if (rsn == null || rsn.isEmpty())
		{
			return;
		}
		if (event.getItems() == null || event.getItems().isEmpty())
		{
			return;
		}

		Set<Integer> accepted = boardState.acceptedItemIds();
		long seq = sequence.incrementAndGet();
		List<DropEvent> drops = new ArrayList<>();
		for (ItemStack item : event.getItems())
		{
			if (item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			if (!accepted.contains(item.getId()))
			{
				continue;
			}
			drops.add(new DropEvent(item.getId(), item.getQuantity(), rsn, seq));
		}

		if (!drops.isEmpty())
		{
			sink.accept(drops);
		}
	}

	private boolean isEnabled(LootRecordType type)
	{
		if (type == null)
		{
			return false;
		}
		switch (type)
		{
			case NPC:
				return config.reportNpcLoot();
			case EVENT:
				return config.reportEventLoot();
			case PICKPOCKET:
				return config.reportPickpocket();
			case PLAYER:
			default:
				return false;
		}
	}
}

package com.osrsbingo.drops;

import java.io.File;
import lombok.Data;
import lombok.ToString;

/**
 * A drop awaiting delivery. Carries its own board code so a mid-flight code
 * change still delivers to the board the drop was earned on.
 *
 * <p>{@code boardCode} is excluded from the generated {@code toString()} —
 * it is a credential and must never appear in a log line.
 */
@Data
public class QueuedDrop
{
	private final DropEvent drop;
	@ToString.Exclude
	private final String boardCode;
	/**
	 * Resolved on the client thread at capture time and carried with the drop,
	 * so the chat line reports the name of the item that actually succeeded
	 * even when several drops are in flight at once.
	 */
	private final String itemName;
	private final File image;
	private final long firstAttemptAt;

	private int attempts;
	private long nextAttemptAt;
	/** Set after a 413 so the retry omits the proof image. */
	private boolean dropImage;

	public QueuedDrop(DropEvent drop, String boardCode, String itemName, File image, long now)
	{
		this.drop = drop;
		this.boardCode = boardCode;
		this.itemName = itemName;
		this.image = image;
		this.firstAttemptAt = now;
		this.nextAttemptAt = now;
	}

	public File effectiveImage()
	{
		return dropImage ? null : image;
	}

	/** Dedupe identity — see {@link DropEvent#getSequence()}. */
	public String key()
	{
		return drop.getSequence() + ":" + drop.getItemId() + ":" + drop.getQuantity();
	}
}

package com.osrsbingo.drops;

import lombok.Value;

/**
 * One item from one loot event, captured on the client thread. Immutable so it
 * can cross to the executor without any further game-state reads.
 */
@Value
public class DropEvent
{
	int itemId;
	int quantity;
	String rsn;
	/**
	 * Monotonic per-loot-event counter. Two identical drops from two kills are
	 * genuinely distinct and must both send; a retry of one must not.
	 */
	long sequence;
}

package com.osrsbingo.board;

/** Inputs to the connection state machine. */
public enum BoardSignal
{
	/** Config has no board code. */
	CODE_BLANK,
	/** The user changed the board code. */
	CODE_CHANGED,
	/** The user clicked Refresh. */
	REFRESH_REQUESTED,
	/** /status returned eventStatus ACTIVE. */
	STATUS_ACTIVE,
	/** /status returned eventStatus DRAFT. */
	STATUS_DRAFT,
	/** /status returned eventStatus ARCHIVED. */
	STATUS_ARCHIVED,
	/** The backend returned 404 for this board code. */
	NOT_FOUND,
	/** Transport failure, 5xx, or 429. */
	NETWORK_ERROR
}

package com.osrsbingo.board;

import com.osrsbingo.BingoConfig;
import com.osrsbingo.api.ApiFailure;
import com.osrsbingo.api.ApiOutcome;
import com.osrsbingo.api.BingoApiClient;
import com.osrsbingo.api.BoardResponse;
import com.osrsbingo.api.BoardStatus;
import com.osrsbingo.api.BoardTile;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import java.util.function.BooleanSupplier;
import lombok.extern.slf4j.Slf4j;

/**
 * Single source of truth for board data and connection state. Everything else
 * in the plugin reads from here and never caches the answer, so there is no
 * second copy of "are we connected" to drift out of sync.
 *
 * <p>Polls the cheap /status endpoint and fetches the full board only when the
 * opaque revision token changes, plus a periodic safety refetch.
 */
@Slf4j
public class BoardState
{
	/** Full board refetch interval regardless of revision (spec §6). */
	private static final long SAFETY_REFETCH_MS = 600_000L;

	private final BingoApiClient api;
	private final ScheduledExecutorService executor;
	private final BingoConfig config;
	private final BooleanSupplier loggedIn;
	private final List<Runnable> listeners = new CopyOnWriteArrayList<>();

	private volatile ConnectionState state = ConnectionState.NO_CODE;
	private volatile BoardResponse board;
	/**
	 * The board code {@link #board} was actually fetched with. Not the same as
	 * {@code config.boardCode()}: ConfigManager writes the new value before it
	 * posts ConfigChanged, so between those two moments config already reads the
	 * new code while the cached — and only validated — board is still the old
	 * one. Reporting must use this, or a drop filtered by board A's item set
	 * gets submitted to board B.
	 */
	private volatile String cachedBoardCode;
	private volatile int pendingCount;
	private volatile Set<Integer> acceptedItemIds = Collections.emptySet();

	private String lastRevision;
	private long lastFullFetchAt;
	private int consecutiveFailures;
	private boolean forceBoardFetch;

	/**
	 * Bumped by every board-code change / explicit refresh. An in-flight
	 * {@link #pollOnce()} captures the value at entry and, before writing any
	 * result of a blocking call into shared state, confirms it is still
	 * current — otherwise the response belongs to a superseded board code (or
	 * a superseded refresh) and is discarded silently. This does not depend
	 * on the executor being single-threaded.
	 */
	private final AtomicLong generation = new AtomicLong();

	/**
	 * Guards read-cancel-reassign of {@link #pollTask} so racing callers
	 * (tick() rescheduling itself, requestRefresh()/refreshSoon() from the
	 * client thread or EDT, stop()) cannot each observe the same future and
	 * each schedule a replacement, which would spawn a second self-
	 * perpetuating poll chain. Never held across a blocking HTTP call.
	 */
	private final Object scheduleLock = new Object();
	private volatile boolean terminated;

	private ScheduledFuture<?> pollTask;
	/** Deadline of the pending {@link #pollTask}, so a periodic reschedule never
	 * clobbers an already-pending sooner poll (e.g. a Refresh's immediate one). */
	private long nextTickDeadlineNanos;

	// NOT @Inject: BingoApiClient and BooleanSupplier have no Guice bindings.
	// BingoPlugin constructs this in startUp().
	public BoardState(BingoApiClient api, ScheduledExecutorService executor, BingoConfig config,
		BooleanSupplier loggedIn)
	{
		this.api = api;
		this.executor = executor;
		this.config = config;
		this.loggedIn = loggedIn;
	}

	public void start()
	{
		terminated = false;
		applySignal(currentCode().isEmpty() ? BoardSignal.CODE_BLANK : BoardSignal.CODE_CHANGED);
		scheduleNext(0L);
	}

	public void stop()
	{
		synchronized (scheduleLock)
		{
			terminated = true;
			if (pollTask != null)
			{
				pollTask.cancel(false);
				pollTask = null;
			}
		}
	}

	public ConnectionState getState()
	{
		return state;
	}

	public BoardResponse getBoard()
	{
		return board;
	}

	/**
	 * @return the board code the currently-cached board was fetched with, or
	 *         null when nothing validated is cached. Callers that are about to
	 *         report a drop MUST use this and must not report when it is null.
	 */
	public String getCachedBoardCode()
	{
		return cachedBoardCode;
	}

	public int getPendingCount()
	{
		return pendingCount;
	}

	public boolean canReport()
	{
		return state.canReport() && !acceptedItemIds.isEmpty();
	}

	/** Immutable union of every tile's accepted item ids. Empty when no board. */
	public Set<Integer> acceptedItemIds()
	{
		return acceptedItemIds;
	}

	public void addListener(Runnable listener)
	{
		listeners.add(listener);
	}

	/**
	 * Removes a previously-registered listener. Null-safe and idempotent — a
	 * caller's {@code shutDown()} may run when {@code startUp()} only
	 * partially completed, or may be called more than once, and must not
	 * throw either way. Removing a listener that was never added (or already
	 * removed) is simply a no-op, exactly like {@link List#remove(Object)}.
	 */
	public void removeListener(Runnable listener)
	{
		if (listener != null)
		{
			listeners.remove(listener);
		}
	}

	public void requestRefresh()
	{
		generation.incrementAndGet();
		applySignal(currentCode().isEmpty() ? BoardSignal.CODE_BLANK : BoardSignal.REFRESH_REQUESTED);
		forceBoardFetch = true;
		scheduleNext(0L);
	}

	public void onBoardCodeChanged()
	{
		generation.incrementAndGet();
		board = null;
		cachedBoardCode = null;
		acceptedItemIds = Collections.emptySet();
		lastRevision = null;
		lastFullFetchAt = 0L;
		consecutiveFailures = 0;
		applySignal(currentCode().isEmpty() ? BoardSignal.CODE_BLANK : BoardSignal.CODE_CHANGED);
		scheduleNext(0L);
	}

	/**
	 * Feeds the outcome of a drop POST back into the state machine (spec §9).
	 * Without this the plugin keeps polling — and keeps reporting — against a
	 * board the backend has just rejected, and every remaining queued drop
	 * fires at it too.
	 *
	 * <ul>
	 *   <li>404 / 401 / 403: the code is dead. Same terminal INVALID_CODE a
	 *       failed status poll produces, which also stops polling.</li>
	 *   <li>409: the event is no longer ACTIVE. Refetch status now rather than
	 *       waiting out the 30s poll interval.</li>
	 *   <li>anything else: a per-drop problem, not a board problem.</li>
	 * </ul>
	 *
	 * <p>Only for the board the drop was actually sent to. The queue retries a
	 * drop for up to an hour, so its 404 can arrive long after the player has
	 * switched codes — and applied blind it would drive the freshly-loaded,
	 * perfectly valid new board to terminal INVALID_CODE, stopping polling and
	 * reporting until the plugin is toggled. Same staleness the {@link
	 * #generation} counter guards on the poll path; here the drop's own code is
	 * matched against the cached one instead, since a rejection is not tied to
	 * any particular poll.
	 *
	 * <p>Called from the submission executor, never the client thread.
	 *
	 * @param boardCode the code the drop was submitted under. A credential: it is
	 *                  only ever compared, never logged or reported.
	 */
	public void onSubmissionRejected(String boardCode, ApiFailure failure)
	{
		if (failure == null)
		{
			return;
		}
		// Not currentCode(): config can already hold a code whose board has not
		// been fetched (let alone validated) yet — cachedBoardCode is the code
		// the live board, and therefore this state machine, belongs to.
		if (boardCode == null || !boardCode.equals(cachedBoardCode))
		{
			return;
		}
		switch (failure.getKind())
		{
			case NOT_FOUND:
			case UNAUTHORIZED:
				applySignal(BoardSignal.NOT_FOUND);
				notifyListeners();
				break;
			case EVENT_NOT_ACTIVE:
				refreshSoon();
				break;
			default:
				break;
		}
	}

	/** Force a full board fetch on the next tick — used after a drop lands. */
	public void refreshSoon()
	{
		forceBoardFetch = true;
		scheduleNext(0L);
	}

	private String currentCode()
	{
		String code = config.boardCode();
		return code == null ? "" : code.trim();
	}

	private void scheduleNext(long delayMs)
	{
		synchronized (scheduleLock)
		{
			if (terminated)
			{
				return;
			}
			long deadline = System.nanoTime() + TimeUnit.MILLISECONDS.toNanos(delayMs);
			// If a poll is already pending sooner-or-equal, keep it. This lets a
			// Refresh's immediate poll survive a concurrent periodic reschedule
			// from a finishing tick() — without it, clicking Refresh could do
			// nothing until the next 30s/5min poll.
			// Subtraction, not `<=`, so the comparison is safe across nanoTime()'s
			// wrap boundary.
			if (pollTask != null && !pollTask.isDone() && nextTickDeadlineNanos - deadline <= 0L)
			{
				return;
			}
			if (pollTask != null)
			{
				pollTask.cancel(false);
			}
			nextTickDeadlineNanos = deadline;
			pollTask = executor.schedule(this::tick, delayMs, TimeUnit.MILLISECONDS);
		}
	}

	private void tick()
	{
		// This task is now running: free the slot so a concurrent Refresh and the
		// periodic reschedule below compete on an empty pollTask rather than each
		// seeing this (still-running) future as the pending one.
		synchronized (scheduleLock)
		{
			pollTask = null;
		}
		try
		{
			pollOnce();
		}
		catch (RuntimeException e)
		{
			log.warn("Bingo poll failed unexpectedly", e);
		}
		finally
		{
			long interval = BoardTransitions.pollIntervalMs(state, consecutiveFailures);
			if (interval > 0L)
			{
				scheduleNext(interval);
			}
		}
	}

	private void pollOnce()
	{
		String code = currentCode();
		if (code.isEmpty())
		{
			applySignal(BoardSignal.CODE_BLANK);
			return;
		}
		if (state.isStopped())
		{
			return;
		}
		// Never poll while logged out — spec §6.
		if (!loggedIn.getAsBoolean())
		{
			return;
		}

		// Captured before the blocking call so a mid-flight board-code change
		// or explicit refresh (which bump this) is detected on return, and the
		// stale response is discarded instead of overwriting newer state.
		long myGeneration = generation.get();

		ApiOutcome<BoardStatus> outcome = api.fetchStatus(code);

		if (generation.get() != myGeneration)
		{
			return;
		}

		if (outcome.isFailed())
		{
			handleFailure(outcome.getFailure());
			return;
		}
		if (!outcome.isOk())
		{
			return;
		}

		consecutiveFailures = 0;
		BoardStatus status = outcome.getValue();
		pendingCount = status.getPendingCount();
		applySignal(signalFor(status.getEventStatus()));

		if (state.isStopped())
		{
			notifyListeners();
			return;
		}

		boolean revisionChanged = !status.getRevision().equals(lastRevision);
		boolean safetyDue = System.currentTimeMillis() - lastFullFetchAt >= SAFETY_REFETCH_MS;
		if (revisionChanged || safetyDue || forceBoardFetch || board == null)
		{
			fetchBoard(code, status.getRevision(), myGeneration);
		}
		notifyListeners();
	}

	private void fetchBoard(String code, String revision, long myGeneration)
	{
		ApiOutcome<BoardResponse> outcome = api.fetchBoard(code);

		if (generation.get() != myGeneration)
		{
			return;
		}

		if (outcome.isFailed())
		{
			handleFailure(outcome.getFailure());
			return;
		}
		BoardResponse fetched = outcome.getValue();
		if (!isUsable(fetched))
		{
			// A 200 whose body is missing required fields is a failed fetch, not
			// a new board: assigning it would NPE on every subsequent poll, every
			// overlay frame, and on the EDT during panel rebuild. Keep the last
			// good cache, do not advance lastRevision, and back off like any
			// other failure so the next poll retries.
			log.warn("Bingo board response was missing required fields; keeping the cached board");
			handleFailure(ApiFailure.of(ApiFailure.Kind.SERVER_ERROR, 0));
			return;
		}
		forceBoardFetch = false;
		lastFullFetchAt = System.currentTimeMillis();
		lastRevision = revision;
		board = fetched;
		// Set together with the board: these two must never disagree, or a drop
		// filtered by this board's items could be posted to a different code.
		cachedBoardCode = code;
		acceptedItemIds = unionItemIds(board);
	}

	/**
	 * Everything downstream — hasActiveCache(), the overlay, the panel, the
	 * needs list — dereferences these without checking. They are non-optional in
	 * the backend's schema, so a response missing one is a broken response, not
	 * a board.
	 */
	private static boolean isUsable(BoardResponse candidate)
	{
		return candidate != null
			&& candidate.getEvent() != null
			&& candidate.getTeam() != null
			&& candidate.getTiles() != null;
	}

	private void handleFailure(ApiFailure failure)
	{
		// UNAUTHORIZED is as terminal as NOT_FOUND: a revoked or wrong-event
		// board code never starts working again on its own, so treating it as a
		// network blip would leave the panel "Reconnecting" forever while every
		// drop failed permanently.
		if (failure.getKind() == ApiFailure.Kind.NOT_FOUND
			|| failure.getKind() == ApiFailure.Kind.UNAUTHORIZED)
		{
			applySignal(BoardSignal.NOT_FOUND);
			notifyListeners();
			return;
		}
		consecutiveFailures++;
		applySignal(BoardSignal.NETWORK_ERROR);
		notifyListeners();
	}

	private static BoardSignal signalFor(String eventStatus)
	{
		if ("ACTIVE".equals(eventStatus))
		{
			return BoardSignal.STATUS_ACTIVE;
		}
		if ("ARCHIVED".equals(eventStatus))
		{
			return BoardSignal.STATUS_ARCHIVED;
		}
		return BoardSignal.STATUS_DRAFT;
	}

	private void applySignal(BoardSignal signal)
	{
		ConnectionState previous = state;
		state = BoardTransitions.next(previous, signal, hasActiveCache());
		if (previous != state)
		{
			notifyListeners();
		}
	}

	/**
	 * A cache only permits offline reporting when it was captured while the
	 * event was ACTIVE — a DRAFT board must never become reportable by going
	 * offline.
	 */
	private boolean hasActiveCache()
	{
		BoardResponse cached = board;
		return cached != null && "ACTIVE".equals(cached.getEvent().getStatus());
	}

	private static Set<Integer> unionItemIds(BoardResponse board)
	{
		if (board == null || board.getTiles() == null)
		{
			return Collections.emptySet();
		}
		Set<Integer> ids = new HashSet<>();
		for (BoardTile tile : board.getTiles())
		{
			if (tile.getItemIds() != null)
			{
				ids.addAll(tile.getItemIds());
			}
		}
		return Collections.unmodifiableSet(ids);
	}

	private void notifyListeners()
	{
		for (Runnable listener : listeners)
		{
			try
			{
				listener.run();
			}
			catch (RuntimeException e)
			{
				log.warn("Bingo listener failed", e);
			}
		}
	}
}

package com.osrsbingo.board;

/**
 * The pure connection state machine. No I/O, no clock, no RuneLite types —
 * every fail-closed guarantee in the plugin is decided here and can be tested
 * exhaustively.
 */
public final class BoardTransitions
{
	private static final long READY_POLL_MS = 30_000L;
	private static final long DRAFT_POLL_MS = 300_000L;
	private static final long BACKOFF_BASE_MS = 30_000L;
	private static final long BACKOFF_CAP_MS = 300_000L;

	private BoardTransitions()
	{
	}

	/**
	 * @param hasActiveCache true only when a board is cached AND that cached
	 *                       board's event status was ACTIVE. A DRAFT or
	 *                       ARCHIVED cache must never enable reporting.
	 */
	public static ConnectionState next(ConnectionState current, BoardSignal signal, boolean hasActiveCache)
	{
		// A stopped state (NO_CODE, ARCHIVED, INVALID_CODE) is terminal: the
		// board is dead until the user does something about it. Without this
		// guard a late or stale poll response (e.g. NETWORK_ERROR arriving
		// after the board was already found ARCHIVED) could silently
		// resurrect it into a reporting-capable state. Only an explicit user
		// action — clearing/changing the code or requesting a refresh — may
		// leave a stopped state; every other signal is a no-op.
		if (current.isStopped()
			&& signal != BoardSignal.CODE_BLANK
			&& signal != BoardSignal.CODE_CHANGED
			&& signal != BoardSignal.REFRESH_REQUESTED)
		{
			return current;
		}

		switch (signal)
		{
			case CODE_BLANK:
				return ConnectionState.NO_CODE;
			case CODE_CHANGED:
			case REFRESH_REQUESTED:
				return ConnectionState.LOADING;
			case STATUS_ACTIVE:
				return ConnectionState.READY;
			case STATUS_DRAFT:
				return ConnectionState.NOT_STARTED;
			case STATUS_ARCHIVED:
				return ConnectionState.ARCHIVED;
			case NOT_FOUND:
				return ConnectionState.INVALID_CODE;
			case NETWORK_ERROR:
				return hasActiveCache ? ConnectionState.OFFLINE_CACHED : ConnectionState.UNREACHABLE;
			default:
				return current;
		}
	}

	/**
	 * @return milliseconds until the next status poll, or 0 when this state
	 *         must generate no traffic at all.
	 */
	public static long pollIntervalMs(ConnectionState state, int consecutiveFailures)
	{
		if (state.isStopped())
		{
			return 0L;
		}
		switch (state)
		{
			case READY:
				return READY_POLL_MS;
			case NOT_STARTED:
				return DRAFT_POLL_MS;
			case OFFLINE_CACHED:
			case UNREACHABLE:
				return backoffMs(consecutiveFailures);
			case LOADING:
			default:
				return READY_POLL_MS;
		}
	}

	private static long backoffMs(int consecutiveFailures)
	{
		int exponent = Math.max(0, Math.min(consecutiveFailures, 16));
		long delay = BACKOFF_BASE_MS << exponent;
		if (delay <= 0 || delay > BACKOFF_CAP_MS)
		{
			return BACKOFF_CAP_MS;
		}
		return delay;
	}
}

package com.osrsbingo.board;

/**
 * Every distinct situation the plugin can be in with respect to its board.
 * Reporting is permitted in exactly two of them — see {@link #canReport()}.
 */
public enum ConnectionState
{
	/** No board code configured. */
	NO_CODE,
	/** First fetch in flight; nothing cached yet. */
	LOADING,
	/** Board loaded and the event is ACTIVE. */
	READY,
	/** Was READY, fetches now failing, cached board still usable. */
	OFFLINE_CACHED,
	/** Loaded, but the event is still DRAFT. */
	NOT_STARTED,
	/** Loaded, and the event is ARCHIVED. Terminal. */
	ARCHIVED,
	/** The backend rejected the board code. Terminal. */
	INVALID_CODE,
	/** Never successfully loaded and the backend is unreachable. */
	UNREACHABLE;

	/**
	 * Drops may only be filtered, screenshotted and submitted in these states.
	 * Everything else is fail-closed: no board data means no reporting.
	 */
	public boolean canReport()
	{
		return this == READY || this == OFFLINE_CACHED;
	}

	/**
	 * Stopped states generate no traffic at all and are left only by a board
	 * code change or a manual refresh.
	 */
	public boolean isStopped()
	{
		return this == NO_CODE || this == ARCHIVED || this == INVALID_CODE;
	}
}

package com.osrsbingo.ui;

import com.osrsbingo.api.BoardResponse;
import com.osrsbingo.api.BoardTile;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Predicate;

/**
 * Turns a board response into the panel's rows, split into three buckets:
 * needed, pending review, and completed. Pure and Swing-free so the bucketing,
 * ordering and missing-item derivation are unit-testable.
 */
public final class NeedsListModel
{
	private static final String KIND_ITEM_DROP = "ITEM_DROP";
	private static final String MODE_COMPLETE_SET = "COMPLETE_SET";

	private NeedsListModel()
	{
	}

	/**
	 * Item tiles still to get: incomplete AND not awaiting review, highest
	 * points first. Pending tiles live in {@link #buildPending} instead, so no
	 * tile is ever listed twice.
	 */
	public static List<NeedsRow> buildNeeded(BoardResponse board)
	{
		return collect(board, tile -> !tile.getProgress().isCompleted() && !tile.isPending());
	}

	/** Incomplete item tiles with a submission awaiting an admin. */
	public static List<NeedsRow> buildPending(BoardResponse board)
	{
		return collect(board, tile -> !tile.getProgress().isCompleted() && tile.isPending());
	}

	/** Completed item tiles. */
	public static List<NeedsRow> buildCompleted(BoardResponse board)
	{
		return collect(board, tile -> tile.getProgress().isCompleted());
	}

	private static List<NeedsRow> collect(BoardResponse board, Predicate<BoardTile> filter)
	{
		if (board == null || board.getTiles() == null)
		{
			return Collections.emptyList();
		}
		List<NeedsRow> rows = new ArrayList<>();
		for (BoardTile tile : board.getTiles())
		{
			if (isItemTile(tile) && filter.test(tile))
			{
				rows.add(toRow(tile));
			}
		}
		rows.sort(Comparator.comparingInt(NeedsRow::getPoints).reversed()
			.thenComparing(NeedsRow::getTitle));
		return rows;
	}

	public static int countCompleted(BoardResponse board)
	{
		if (board == null || board.getTiles() == null)
		{
			return 0;
		}
		int count = 0;
		for (BoardTile tile : board.getTiles())
		{
			if (isItemTile(tile) && tile.getProgress().isCompleted())
			{
				count++;
			}
		}
		return count;
	}

	public static int countTotalItemTiles(BoardResponse board)
	{
		if (board == null || board.getTiles() == null)
		{
			return 0;
		}
		int count = 0;
		for (BoardTile tile : board.getTiles())
		{
			if (isItemTile(tile))
			{
				count++;
			}
		}
		return count;
	}

	private static boolean isItemTile(BoardTile tile)
	{
		return KIND_ITEM_DROP.equals(tile.getKind())
			&& tile.getItemIds() != null
			&& !tile.getItemIds().isEmpty();
	}

	private static NeedsRow toRow(BoardTile tile)
	{
		List<Integer> accepted = tile.getItemIds();
		boolean completeSet = MODE_COMPLETE_SET.equals(tile.getCountMode());
		List<Integer> missing = completeSet ? missingItems(tile) : Collections.emptyList();
		int icon = accepted.isEmpty() ? 0 : accepted.get(0);

		return new NeedsRow(
			tile.getId(),
			tile.getTitle(),
			tile.getPoints(),
			tile.getProgress().getCurrent(),
			tile.getProgress().getTarget(),
			tile.isPending(),
			completeSet,
			icon,
			Collections.unmodifiableList(new ArrayList<>(accepted)),
			Collections.unmodifiableList(missing));
	}

	/**
	 * Accepted ids with no approved submission yet. Only meaningful for
	 * COMPLETE_SET — an ANY tile has nothing to be individually missing.
	 */
	private static List<Integer> missingItems(BoardTile tile)
	{
		Set<Integer> obtained = tile.getObtainedItemIds() == null
			? Collections.emptySet()
			: new HashSet<>(tile.getObtainedItemIds());
		List<Integer> missing = new ArrayList<>();
		for (Integer id : tile.getItemIds())
		{
			if (!obtained.contains(id))
			{
				missing.add(id);
			}
		}
		return missing;
	}
}

package com.osrsbingo.ui;

import com.osrsbingo.api.BoardResponse;
import com.osrsbingo.api.BoardTile;
import com.osrsbingo.board.BoardState;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.util.ArrayList;
import java.util.List;
import java.util.function.BooleanSupplier;
import java.util.function.ToIntFunction;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The bingo board drawn over the viewport: a {@code size × size} grid of named,
 * tinted cells at their true board positions. Reads {@link BoardState} and never
 * fetches anything itself.
 *
 * <p>This extends {@link Overlay} directly rather than {@link
 * net.runelite.client.ui.overlay.OverlayPanel}. RuneLite's {@code
 * OverlayRenderer} translates the {@link Graphics2D} origin to the overlay's
 * current on-screen location, then calls {@link #render(Graphics2D)}, and only
 * afterwards resizes {@code getBounds()} to whatever {@link Dimension} this
 * method returns. So inside {@code render} the graphics origin (0, 0) already
 * <em>is</em> the overlay's top-left corner: everything is painted relative to
 * local (0, 0) and an accurate {@link Dimension} is handed back so RuneLite (not
 * this class) owns bounds, dragging and snapping. {@code getBounds()} is never
 * read for positioning here.
 *
 * <p>The grid-math and text-wrap logic is factored into pure package-private
 * static helpers ({@link #byPosition}, {@link #rowOf}, {@link #colOf}, {@link
 * #cellColor}, {@link #wrapLabel}) so it is unit-tested without a live
 * {@link Graphics2D}. The per-frame allocations (a tile array and a couple of
 * short line lists) are the routine cost of a hand-painted overlay.
 */
public class BingoOverlay extends Overlay
{
	private static final int CELL_W = 70;
	private static final int CELL_H = 48;
	private static final int GAP = 2;
	private static final int PADDING = 8;
	private static final int TEXT_PAD = 4;
	private static final int MAX_TEXT_LINES = 2;

	private static final Color BACKGROUND = new Color(0, 0, 0, 150);
	private static final Color CELL_BORDER = Color.DARK_GRAY;
	private static final Color EMPTY_CELL = new Color(45, 45, 45);
	private static final Color TEXT_COLOR = Color.WHITE;
	private static final Color COMPLETED = new Color(60, 160, 60);
	private static final Color PENDING = new Color(190, 160, 50);
	private static final Color OUTSTANDING = new Color(70, 70, 70);

	private final BoardState boardState;
	private final BooleanSupplier visible;

	// NOT @Inject: BoardState has no Guice binding; BingoPlugin builds this.
	public BingoOverlay(BoardState boardState, BooleanSupplier visible)
	{
		this.boardState = boardState;
		this.visible = visible;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!visible.getAsBoolean())
		{
			return null;
		}
		BoardResponse board = boardState.getBoard();
		if (board == null)
		{
			return null;
		}
		int size = board.getEvent().getSize();
		if (size <= 0)
		{
			return null;
		}

		BoardTile[] byPos = byPosition(board.getTiles(), size);
		FontMetrics fm = graphics.getFontMetrics();
		int lineHeight = fm.getHeight();

		int gridWidth = size * CELL_W + (size - 1) * GAP;
		int gridHeight = size * CELL_H + (size - 1) * GAP;
		int width = gridWidth + PADDING * 2;
		int height = gridHeight + PADDING * 2;

		graphics.setColor(BACKGROUND);
		graphics.fillRect(0, 0, width, height);

		for (int position = 0; position < size * size; position++)
		{
			int x = PADDING + colOf(position, size) * (CELL_W + GAP);
			int y = PADDING + rowOf(position, size) * (CELL_H + GAP);
			BoardTile tile = byPos[position];

			if (tile == null)
			{
				graphics.setColor(EMPTY_CELL);
				graphics.drawRect(x, y, CELL_W, CELL_H);
				continue;
			}

			graphics.setColor(cellColor(tile));
			graphics.fillRect(x, y, CELL_W, CELL_H);
			graphics.setColor(CELL_BORDER);
			graphics.drawRect(x, y, CELL_W, CELL_H);

			List<String> lines = wrapLabel(tile.getTitle(), CELL_W - TEXT_PAD * 2, MAX_TEXT_LINES,
				fm::stringWidth);
			graphics.setColor(TEXT_COLOR);
			int textY = y + (CELL_H - lines.size() * lineHeight) / 2 + fm.getAscent();
			for (String line : lines)
			{
				int textX = x + (CELL_W - fm.stringWidth(line)) / 2;
				graphics.drawString(line, textX, textY);
				textY += lineHeight;
			}
		}

		return new Dimension(width, height);
	}

	/** Row of a position in a {@code size}-wide grid. */
	static int rowOf(int position, int size)
	{
		return position / size;
	}

	/** Column of a position in a {@code size}-wide grid. */
	static int colOf(int position, int size)
	{
		return position % size;
	}

	/**
	 * Tiles indexed by board position: array length {@code size*size}, {@code
	 * null} where no tile sits. Positions outside the grid are ignored (never
	 * throw). MANUAL tiles occupy their cell like any other — they have a title
	 * and a completed state, just no items.
	 */
	static BoardTile[] byPosition(List<BoardTile> tiles, int size)
	{
		BoardTile[] byPos = new BoardTile[size * size];
		if (tiles == null)
		{
			return byPos;
		}
		for (BoardTile tile : tiles)
		{
			int position = tile.getPosition();
			if (position >= 0 && position < byPos.length)
			{
				byPos[position] = tile;
			}
		}
		return byPos;
	}

	/** Green completed, else yellow pending, else grey outstanding. */
	static Color cellColor(BoardTile tile)
	{
		if (tile.getProgress().isCompleted())
		{
			return COMPLETED;
		}
		if (tile.isPending())
		{
			return PENDING;
		}
		return OUTSTANDING;
	}

	/**
	 * Greedy word-wrap of {@code text} into at most {@code maxLines} lines no
	 * wider than {@code maxWidth} (measured by {@code widthOf}). If words remain
	 * after the last line, or a single word is itself too wide, the last line is
	 * trimmed and ends with an ellipsis. {@code widthOf} is injected so the logic
	 * is testable without a live {@link Graphics2D}.
	 */
	static List<String> wrapLabel(String text, int maxWidth, int maxLines, ToIntFunction<String> widthOf)
	{
		List<String> lines = new ArrayList<>();
		if (text == null || text.trim().isEmpty())
		{
			return lines;
		}
		String[] words = text.trim().split("\\s+");
		int i = 0;
		while (i < words.length && lines.size() < maxLines)
		{
			StringBuilder line = new StringBuilder(words[i++]);
			while (i < words.length && widthOf.applyAsInt(line + " " + words[i]) <= maxWidth)
			{
				line.append(' ').append(words[i++]);
			}
			lines.add(line.toString());
		}

		boolean wordsRemain = i < words.length;
		int last = lines.size() - 1;
		if (last >= 0 && (wordsRemain || widthOf.applyAsInt(lines.get(last)) > maxWidth))
		{
			lines.set(last, ellipsize(lines.get(last), maxWidth, widthOf));
		}
		return lines;
	}

	/** Trims trailing characters until {@code result} fits {@code maxWidth}; always ends with an ellipsis. */
	private static String ellipsize(String s, int maxWidth, ToIntFunction<String> widthOf)
	{
		int len = s.length();
		while (len > 0 && widthOf.applyAsInt(s.substring(0, len) + "…") > maxWidth)
		{
			len--;
		}
		return s.substring(0, len) + "…";
	}
}

package com.osrsbingo.ui;

import com.osrsbingo.api.BoardResponse;
import com.osrsbingo.board.BoardState;
import com.osrsbingo.board.ConnectionState;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.api.ItemComposition;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * The sidebar panel: a connection status line, team summary, and the
 * points-descending list of tiles the team still needs.
 */
public class BingoPanel extends PluginPanel
{
	private static final String UNKNOWN_ITEM_NAME = "unknown item";

	private final BoardState boardState;
	private final ItemManager itemManager;
	private final ClientThread clientThread;
	private final ConfigManager configManager;

	/**
	 * Item id -> resolved name. Names never change, so an id is resolved at
	 * most once. Written on the client thread (see {@link #resolveMissingNames}),
	 * read on the EDT (see {@link #detailLine}) — hence the concurrent map.
	 */
	private final Map<Integer, String> itemNameCache = new ConcurrentHashMap<>();

	private final JLabel eventLabel = new JLabel();
	private final JLabel statusLabel = new JLabel();
	private final JLabel teamLabel = new JLabel();
	private final JLabel progressLabel = new JLabel();
	private final JPanel rowsPanel = new JPanel();
	private final JButton overlayToggle = new JButton();

	public BingoPanel(BoardState boardState, ItemManager itemManager, ClientThread clientThread,
		ConfigManager configManager)
	{
		this.boardState = boardState;
		this.itemManager = itemManager;
		this.clientThread = clientThread;
		this.configManager = configManager;

		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));

		add(buildHeader(), BorderLayout.NORTH);

		rowsPanel.setLayout(new BoxLayout(rowsPanel, BoxLayout.Y_AXIS));
		rowsPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(rowsPanel, BorderLayout.CENTER);

		refresh();
	}

	private JPanel buildHeader()
	{
		JPanel header = new JPanel();
		header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel titleRow = new JPanel(new BorderLayout());
		titleRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		JLabel title = new JLabel("OSRS Bingo");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		titleRow.add(title, BorderLayout.WEST);

		JButton refreshButton = new JButton("Refresh");
		refreshButton.setFocusable(false);
		refreshButton.addActionListener(e -> boardState.requestRefresh());
		titleRow.add(refreshButton, BorderLayout.EAST);
		header.add(titleRow);

		overlayToggle.setFocusable(false);
		overlayToggle.setText(overlayToggleText());
		overlayToggle.addActionListener(e ->
		{
			OverlayVisibility.set(configManager, !OverlayVisibility.isVisible(configManager));
			overlayToggle.setText(overlayToggleText());
		});
		JPanel overlayRow = new JPanel(new BorderLayout());
		overlayRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
		overlayRow.add(overlayToggle, BorderLayout.WEST);
		header.add(overlayRow);

		eventLabel.setFont(FontManager.getRunescapeSmallFont());
		eventLabel.setForeground(Color.LIGHT_GRAY);
		header.add(eventLabel);

		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		header.add(statusLabel);

		header.add(javax.swing.Box.createVerticalStrut(6));

		teamLabel.setFont(FontManager.getRunescapeBoldFont());
		teamLabel.setForeground(Color.WHITE);
		header.add(teamLabel);

		progressLabel.setFont(FontManager.getRunescapeSmallFont());
		progressLabel.setForeground(Color.LIGHT_GRAY);
		header.add(progressLabel);

		header.add(javax.swing.Box.createVerticalStrut(6));
		return header;
	}

	private String overlayToggleText()
	{
		return "Board overlay: " + (OverlayVisibility.isVisible(configManager) ? "On" : "Off");
	}

	/** Safe to call from the poller thread; marshals onto the EDT. */
	public void refresh()
	{
		SwingUtilities.invokeLater(this::rebuild);
	}

	private void rebuild()
	{
		ConnectionState state = boardState.getState();
		statusLabel.setText(statusText(state));
		statusLabel.setForeground(statusColor(state));

		BoardResponse board = boardState.getBoard();
		rowsPanel.removeAll();

		if (board == null)
		{
			eventLabel.setText("");
			teamLabel.setText("");
			progressLabel.setText("");
			rowsPanel.revalidate();
			rowsPanel.repaint();
			return;
		}

		eventLabel.setText(board.getEvent().getName());
		teamLabel.setText(board.getTeam().getName() + " · " + board.getTeam().getScore() + " pts"
			+ rankSuffix(board));

		int completed = NeedsListModel.countCompleted(board);
		int total = NeedsListModel.countTotalItemTiles(board);
		progressLabel.setText(completed + "/" + total + " tiles · "
			+ boardState.getPendingCount() + " pending");

		if (total == 0)
		{
			rowsPanel.add(hint("This board has no item tiles — drops can't be auto-logged."));
			rowsPanel.revalidate();
			rowsPanel.repaint();
			return;
		}

		List<NeedsRow> needed = NeedsListModel.buildNeeded(board);
		List<NeedsRow> pending = NeedsListModel.buildPending(board);
		List<NeedsRow> done = NeedsListModel.buildCompleted(board);

		if (needed.isEmpty() && pending.isEmpty())
		{
			rowsPanel.add(hint("Every tile is done. Nice."));
		}
		else if (needed.isEmpty())
		{
			rowsPanel.add(hint("Nothing left to hunt — everything else is awaiting review."));
		}

		Set<Integer> missingIds = new HashSet<>();

		if (!needed.isEmpty())
		{
			JLabel heading = new JLabel("STILL NEEDED");
			heading.setFont(FontManager.getRunescapeSmallFont());
			heading.setForeground(Color.LIGHT_GRAY);
			rowsPanel.add(heading);
			rowsPanel.add(Box.createVerticalStrut(4));

			for (NeedsRow row : needed)
			{
				rowsPanel.add(renderRow(row, missingIds));
				rowsPanel.add(Box.createVerticalStrut(4));
			}
		}

		// Pending and completed collapse so the panel stays about what to hunt.
		// Pending starts open (it is the actionable one — a stuck submission is
		// worth noticing); completed starts closed.
		if (!pending.isEmpty())
		{
			rowsPanel.add(Box.createVerticalStrut(6));
			rowsPanel.add(collapsible("Pending", pending, true, missingIds));
		}
		if (!done.isEmpty())
		{
			rowsPanel.add(Box.createVerticalStrut(6));
			rowsPanel.add(collapsible("Completed", done, false, missingIds));
		}

		rowsPanel.revalidate();
		rowsPanel.repaint();

		if (!missingIds.isEmpty())
		{
			resolveMissingNames(missingIds);
		}
	}

	/**
	 * Resolves item names on the client thread — ItemManager.getItemComposition
	 * is a bare passthrough to Client state, which is unsafe to touch off the
	 * client thread. Only ids that are actually new are added to the cache, and
	 * a follow-up refresh() is scheduled only if at least one new name was
	 * cached — otherwise a stale/never-resolvable id would trigger refresh()
	 * forever, since it would remain "missing" on every subsequent rebuild().
	 */
	private void resolveMissingNames(Set<Integer> ids)
	{
		clientThread.invoke(() ->
		{
			boolean resolvedAny = false;
			for (int id : ids)
			{
				if (itemNameCache.containsKey(id))
				{
					continue;
				}
				String name;
				try
				{
					ItemComposition composition = itemManager.getItemComposition(id);
					name = composition == null ? null : composition.getName();
				}
				catch (RuntimeException e)
				{
					name = null;
				}
				itemNameCache.put(id, name == null || name.isEmpty() ? UNKNOWN_ITEM_NAME : name);
				resolvedAny = true;
			}
			if (resolvedAny)
			{
				refresh();
			}
		});
	}

	/**
	 * A click-to-toggle section. Swing has no built-in disclosure widget, so
	 * this is a header label that flips the visibility of a content panel.
	 */
	private JPanel collapsible(String title, List<NeedsRow> rows, boolean startExpanded, Set<Integer> missingIds)
	{
		JPanel container = new JPanel();
		container.setLayout(new BoxLayout(container, BoxLayout.Y_AXIS));
		container.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setBackground(ColorScheme.DARK_GRAY_COLOR);
		content.setVisible(startExpanded);

		JLabel header = new JLabel(headerText(title, rows.size(), startExpanded));
		header.setFont(FontManager.getRunescapeSmallFont());
		header.setForeground(Color.LIGHT_GRAY);
		header.setCursor(new Cursor(Cursor.HAND_CURSOR));
		header.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				content.setVisible(!content.isVisible());
				header.setText(headerText(title, rows.size(), content.isVisible()));
				container.revalidate();
				container.repaint();
			}
		});

		for (NeedsRow row : rows)
		{
			content.add(renderRow(row, missingIds));
			content.add(Box.createVerticalStrut(4));
		}

		container.add(header);
		container.add(content);
		return container;
	}

	private static String headerText(String title, int count, boolean expanded)
	{
		return (expanded ? "▾ " : "▸ ") + title + " (" + count + ")";
	}

	private String rankSuffix(BoardResponse board)
	{
		if (board.getLeaderboard() == null || board.getLeaderboard().isEmpty())
		{
			return "";
		}
		int rank = 1;
		for (BoardResponse.LeaderboardEntry entry : board.getLeaderboard())
		{
			if (entry.getTeamId().equals(board.getTeam().getId()))
			{
				return " · " + ordinal(rank) + " of " + board.getLeaderboard().size();
			}
			rank++;
		}
		return "";
	}

	private static String ordinal(int n)
	{
		if (n % 100 >= 11 && n % 100 <= 13)
		{
			return n + "th";
		}
		switch (n % 10)
		{
			case 1:
				return n + "st";
			case 2:
				return n + "nd";
			case 3:
				return n + "rd";
			default:
				return n + "th";
		}
	}

	private JLabel hint(String text)
	{
		JLabel label = new JLabel("<html><body style='width:150px'>" + text + "</body></html>");
		label.setFont(FontManager.getRunescapeSmallFont());
		label.setForeground(Color.LIGHT_GRAY);
		return label;
	}

	private JPanel renderRow(NeedsRow row, Set<Integer> missingIds)
	{
		JPanel panel = new JPanel(new BorderLayout(6, 0));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createEmptyBorder(4, 4, 4, 4));

		if (row.getIconItemId() > 0)
		{
			JLabel icon = new JLabel();
			icon.setPreferredSize(new Dimension(32, 32));
			AsyncBufferedImage image = itemManager.getImage(row.getIconItemId());
			image.addTo(icon);
			panel.add(icon, BorderLayout.WEST);
		}

		JPanel text = new JPanel(new GridLayout(0, 1));
		text.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JLabel title = new JLabel(row.getTitle());
		title.setFont(FontManager.getRunescapeSmallFont());
		title.setForeground(row.isPending() ? ColorScheme.PROGRESS_INPROGRESS_COLOR : Color.WHITE);
		text.add(title);

		JLabel meta = new JLabel(row.getCurrent() + "/" + row.getTarget()
			+ " · " + row.getPoints() + " pts" + (row.isPending() ? " · pending" : ""));
		meta.setFont(FontManager.getRunescapeSmallFont());
		meta.setForeground(Color.LIGHT_GRAY);
		text.add(meta);

		String detail = detailLine(row, missingIds);
		if (detail != null)
		{
			JLabel detailLabel = new JLabel("<html><body style='width:120px'>" + detail + "</body></html>");
			detailLabel.setFont(FontManager.getRunescapeSmallFont());
			detailLabel.setForeground(Color.GRAY);
			text.add(detailLabel);
		}

		panel.add(text, BorderLayout.CENTER);
		return panel;
	}

	/**
	 * COMPLETE_SET tiles list the specific items still missing; ANY tiles list
	 * what would count, since nothing can be individually missing.
	 */
	private String detailLine(NeedsRow row, Set<Integer> missingIds)
	{
		List<Integer> ids = row.isCompleteSet() ? row.getMissingItemIds() : row.getAcceptedItemIds();
		if (ids.isEmpty())
		{
			return null;
		}
		String prefix = row.isCompleteSet() ? "missing: " : "any of: ";
		StringBuilder sb = new StringBuilder(prefix);
		int shown = Math.min(ids.size(), 3);
		for (int i = 0; i < shown; i++)
		{
			if (i > 0)
			{
				sb.append(", ");
			}
			sb.append(itemName(ids.get(i), missingIds));
		}
		if (ids.size() > shown)
		{
			sb.append(", +").append(ids.size() - shown).append(" more");
		}
		return sb.toString();
	}

	/**
	 * Never touches ItemManager/Client — reads only the cache, which is
	 * populated on the client thread by {@link #resolveMissingNames}. Ids not
	 * yet cached get a harmless placeholder and are recorded as missing so the
	 * caller can schedule resolution.
	 */
	private String itemName(int itemId, Set<Integer> missingIds)
	{
		String cached = itemNameCache.get(itemId);
		if (cached != null)
		{
			return cached;
		}
		missingIds.add(itemId);
		return "…";
	}

	private static String statusText(ConnectionState state)
	{
		switch (state)
		{
			case NO_CODE:
				return "Paste your board code in settings";
			case LOADING:
				return "Connecting…";
			case READY:
				return "● Connected";
			case OFFLINE_CACHED:
				return "⚠ Reconnecting — drops are queued";
			case NOT_STARTED:
				return "This bingo hasn't started yet";
			case ARCHIVED:
				return "This bingo has ended";
			case INVALID_CODE:
				return "Board code not recognized";
			case UNREACHABLE:
			default:
				return "Can't reach the bingo server";
		}
	}

	private static Color statusColor(ConnectionState state)
	{
		if (state == ConnectionState.READY)
		{
			return ColorScheme.PROGRESS_COMPLETE_COLOR;
		}
		if (state == ConnectionState.OFFLINE_CACHED || state == ConnectionState.LOADING)
		{
			return ColorScheme.PROGRESS_INPROGRESS_COLOR;
		}
		return ColorScheme.PROGRESS_ERROR_COLOR;
	}
}

package com.osrsbingo.ui;

import com.osrsbingo.BingoConfig;
import net.runelite.client.config.ConfigManager;

/**
 * Persists the board-overlay on/off state as a hidden config value under group
 * {@link BingoConfig#GROUP}, key {@code showOverlay}. It is deliberately NOT a
 * {@code @ConfigItem}, so it sticks across sessions without appearing in the
 * RuneLite Settings panel — the toggle lives in {@link BingoPanel} instead.
 */
public final class OverlayVisibility
{
	static final String KEY = "showOverlay";

	private OverlayVisibility()
	{
	}

	public static boolean isVisible(ConfigManager configManager)
	{
		return Boolean.parseBoolean(configManager.getConfiguration(BingoConfig.GROUP, KEY));
	}

	public static void set(ConfigManager configManager, boolean visible)
	{
		configManager.setConfiguration(BingoConfig.GROUP, KEY, Boolean.toString(visible));
	}
}

package com.osrsbingo.ui;

import com.osrsbingo.api.BoardResponse;
import com.osrsbingo.board.BoardState;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A small always-available box showing the team name and the local clock. A
 * SEPARATE overlay from {@link BingoOverlay}, independently draggable, and shown
 * whenever a board is loaded — independent of the grid toggle, so the team and
 * time are visible without the full grid on screen.
 *
 * <p>Same rendering discipline as {@link BingoOverlay}: paint at local (0, 0),
 * return a {@link Dimension}, no I/O — reads {@link BoardState} and the system
 * clock only. The formatted clock string is rebuilt each frame (cheap).
 */
public class BingoInfoOverlay extends Overlay
{
	private static final int PADDING = 6;
	private static final int LINE_GAP = 2;
	private static final Color BACKGROUND = new Color(0, 0, 0, 150);
	private static final Color TEAM_COLOR = Color.WHITE;
	private static final Color CLOCK_COLOR = Color.LIGHT_GRAY;
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");

	private final BoardState boardState;

	// NOT @Inject: BoardState has no Guice binding; BingoPlugin builds this.
	public BingoInfoOverlay(BoardState boardState)
	{
		this.boardState = boardState;
		// A different default corner from BingoOverlay's TOP_LEFT so the two
		// overlays don't stack in the same snap corner on first launch; both
		// stay independently draggable.
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		BoardResponse board = boardState.getBoard();
		if (board == null)
		{
			return null;
		}

		String team = board.getTeam().getName();
		String clock = formatClock(LocalDateTime.now());

		FontMetrics fm = graphics.getFontMetrics();
		int lineHeight = fm.getHeight();
		int contentWidth = Math.max(fm.stringWidth(team), fm.stringWidth(clock));
		int width = contentWidth + PADDING * 2;
		int height = lineHeight * 2 + LINE_GAP + PADDING * 2;

		graphics.setColor(BACKGROUND);
		graphics.fillRect(0, 0, width, height);

		int textY = PADDING + fm.getAscent();
		graphics.setColor(TEAM_COLOR);
		graphics.drawString(team, PADDING, textY);
		textY += lineHeight + LINE_GAP;
		graphics.setColor(CLOCK_COLOR);
		graphics.drawString(clock, PADDING, textY);

		return new Dimension(width, height);
	}

	/** Local date + time as {@code yyyy-MM-dd HH:mm} (24-hour). */
	static String formatClock(LocalDateTime now)
	{
		return CLOCK.format(now);
	}
}

